import AppKit

/// A move the runner does not offer, in one sentence (spec §11 TU-8 (2), (6)).
struct TutorialRefusal: Error {
    let sentence: String
}

/// How a step was left: its wait met, Next, or Skip.
enum TutorialAdvance: String {
    case wait, next, skip
}

/// How a step was entered. A forward entry — start, Next, Skip, a met wait —
/// is a trigger; a Back entry is not (spec §11 TU-8 (3)).
enum TutorialEntry {
    case forward, back
}

/// What the last Show Me did (spec §11 TU-9).
struct TutorialShowMeOutcome {
    let step: Int
    let ok: Bool
    let error: String?
    /// Each call's result text, in order.
    let results: [String]
    /// The files an `export` call was sent to write.
    let paths: [String]
}

/// One tutorial running in one editor window, with no chrome (spec §11
/// TU-8): its needs checked at the start, each step's baseline and reveal as
/// it begins, its wait read after events, and Back, Skip, Next, Exit and Show
/// Me (`TutorialShowMe.swift`, TU-9). The panel that shows it is TU3's; the
/// dev tools (`AgentServer+Tutorials.swift`) drive it until then.
///
/// **Event-driven.** A committed document or view-state change
/// (`documentDidChange`, from the editor's `projectDidChange`), a playhead
/// move (`trigger`, from `inspectorPlayheadMoved`), a rate change, the
/// window's sheet beginning or ending, an export started and a forward step
/// entry each call `trigger()`, which schedules ONE coalesced evaluation on
/// the next main turn — a documented `DispatchQueue.main.async` seam — so the
/// event that met a wait has finished first. Nothing polls. While a Show Me
/// runs every evaluation is held, and one runs after its last entry.
///
/// Owned by `EditorViewController.tutorialRunner`; Exit sets that to nil and
/// undoes nothing, and closing the window ends it. Main only.
final class TutorialRunner {
    let tutorial: Tutorial
    weak var editor: EditorViewController?
    weak var document: ProjectDocument?

    /// The current step's index, 0-based; the last step's once finished.
    private(set) var index = 0
    private(set) var finished = false
    private var baseline: TutorialBaseline
    /// `$created` now: the ids added by the latest step, or Show Me call,
    /// that added any.
    var created: [UInt32] = []
    /// `created` as each step began, so Back restores it.
    private var createdAtBegin: [Int: [UInt32]] = [:]
    private var latches = TutorialLatches()
    private var revealRefused: String?
    private var completed: [(step: Int, by: TutorialAdvance)] = []
    private var evaluationPending = false
    private var observers: [NSObjectProtocol] = []
    /// The clips' JSON the waits read; the runner's own, so letting the
    /// runner go on any thread touches nothing another runner or main reads.
    private let clipCache: TutorialClipCache

    // Show Me's state (`TutorialShowMe.swift`).
    /// True from the press until the last entry's answer is back.
    var showMeRunning = false
    /// A trigger arrived while a Show Me ran.
    var heldEvaluation = false
    /// The Show Me in flight; its generation drops a stale completion.
    var showMeRun: TutorialShowMeRun?
    var showMeGeneration = 0
    var lastShowMe: TutorialShowMeOutcome?

    private init(tutorial: Tutorial, editor: EditorViewController, document: ProjectDocument) {
        self.tutorial = tutorial
        self.editor = editor
        self.document = document
        let cache = TutorialClipCache()
        clipCache = cache
        baseline = TutorialBaseline(document: document, cache: cache)
    }

    /// Safe on any thread: `NotificationCenter` is thread-safe, and the clip
    /// cache is the runner's own.
    deinit {
        for observer in observers { NotificationCenter.default.removeObserver(observer) }
    }

    // MARK: - Start and exit

    /// Starts `tutorial` in `editor`'s window, replacing any running there;
    /// refused, starting nothing, when its needs are unmet.
    @discardableResult
    static func start(_ tutorial: Tutorial, in editor: EditorViewController) throws
        -> TutorialRunner {
        guard let document = editor.document else {
            throw TutorialRefusal(sentence: "This window has no project.")
        }
        if let sentence = TutorialWait.needsSentence(
            tutorial.needs, in: document.editedProject.snapshot)
        {
            throw TutorialRefusal(sentence: sentence)
        }
        let runner = TutorialRunner(tutorial: tutorial, editor: editor, document: document)
        editor.tutorialRunner = runner
        runner.observeSheets(editor.view.window)
        runner.begin(0, .forward)
        return runner
    }

    /// Ends the tutorial; the project and its undo history stay as they are.
    func exit() {
        guard let editor, editor.tutorialRunner === self else { return }
        editor.tutorialRunner = nil
    }

    private func observeSheets(_ window: NSWindow?) {
        guard let window else { return }
        for name in [NSWindow.willBeginSheetNotification, NSWindow.didEndSheetNotification] {
            observers.append(
                NotificationCenter.default.addObserver(forName: name, object: window, queue: nil) {
                    [weak self] _ in self?.trigger()
                })
        }
    }

    // MARK: - Triggers

    /// Schedules one evaluation on the next main turn, or holds it while a
    /// Show Me runs.
    func trigger() {
        if showMeRunning {
            heldEvaluation = true
            return
        }
        guard !evaluationPending else { return }
        evaluationPending = true
        DispatchQueue.main.async { [weak self] in self?.evaluate() }
    }

    /// A committed change or a view-state change; a live tick is ignored.
    func documentDidChange(isLive: Bool) {
        guard !isLive else { return }
        trigger()
    }

    func playbackRateChanged(_ rate: Float) {
        if rate != 0 { latches.playing = true }
        trigger()
    }

    /// The sheet's Export… or Add to Queue, or the `export` tool, started one.
    func noteExportStarted() {
        latches.exportStarted = true
        trigger()
    }

    private func evaluate() {
        evaluationPending = false
        if showMeRunning {
            heldEvaluation = true
            return
        }
        guard !finished, let editor, editor.tutorialRunner === self, let document else { return }
        let step = currentStep
        guard !step.wait.isEmpty,
              TutorialWait.met(
                step.wait, baseline: baseline, created: created, latches: latches,
                document: document, window: editor.view.window, cache: clipCache)
        else { return }
        advance(by: .wait)
    }

    // MARK: - Navigation

    var currentStep: TutorialStep { tutorial.steps[index] }

    /// `$selection`: the step's start selection, in time order.
    var selectionAtStart: [UInt32] { baseline.selection }

    /// Begins step `next`: its baseline, then its reveal; a forward entry is
    /// a trigger.
    private func begin(_ next: Int, _ entry: TutorialEntry) {
        index = next
        finished = false
        switch entry {
        case .forward: createdAtBegin[next] = created
        case .back: created = createdAtBegin[next] ?? created
        }
        if let document { baseline = TutorialBaseline(document: document, cache: clipCache) }
        latches = TutorialLatches()
        revealRefused = nil
        if let reveal = currentStep.reveal {
            if let inspector = editor?.inspector, inspector.isViewLoaded {
                revealRefused = inspector.reveal(reveal)
            } else {
                revealRefused = "The window has no inspector."
            }
        }
        if entry == .forward { trigger() }
    }

    private func advance(by how: TutorialAdvance) {
        completed.append((index + 1, how))
        if let document {
            let snapshot = document.editedProject.snapshot
            let added = snapshot.clips.map(\.id).filter { !baseline.clipIDs.contains($0) }
            if !added.isEmpty { created = TutorialVariables.timeOrdered(added, in: snapshot) }
        }
        if index + 1 < tutorial.steps.count {
            begin(index + 1, .forward)
        } else {
            finished = true
        }
    }

    private func refuseWhileShowMe() throws {
        if showMeRunning { throw TutorialRefusal(sentence: "Show Me is still running.") }
    }

    func next() throws {
        try refuseWhileShowMe()
        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
        guard currentStep.wait.isEmpty else {
            throw TutorialRefusal(
                sentence: "This step goes on by itself once it is done; Next is only on a step "
                    + "with nothing to wait for.")
        }
        advance(by: .next)
    }

    func skip() throws {
        try refuseWhileShowMe()
        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
        guard currentStep.optional else {
            throw TutorialRefusal(sentence: "Only an optional step can be skipped.")
        }
        advance(by: .skip)
    }

    func back() throws {
        try refuseWhileShowMe()
        let target: Int
        if finished {
            target = index
        } else {
            guard index > 0 else { throw TutorialRefusal(sentence: "This is the first step.") }
            target = index - 1
        }
        completed.removeAll { $0.step >= target + 1 }
        begin(target, .back)
    }

    // MARK: - The state

    /// What the panel offers now, in its order.
    var offers: [String] {
        var out: [String] = []
        if finished || index > 0 { out.append("back") }
        if !finished {
            let step = currentStep
            if !step.showMe.isEmpty { out.append("show_me") }
            if step.optional { out.append("skip") }
            if step.wait.isEmpty { out.append("next") }
        }
        out.append("exit")
        return out
    }

    /// The dev tools' answer: where the tutorial is and what it holds.
    func state() -> [String: Any] {
        let step = currentStep
        var reveal: Any = NSNull()
        if let shown = step.reveal {
            reveal = [
                "tab": shown.tab.title.lowercased(),
                "sub_tab": shown.subTab.map { $0.rawValue as Any } ?? NSNull(),
                "section": shown.section.map { $0 as Any } ?? NSNull(),
            ] as [String: Any]
        }
        var last: Any = NSNull()
        if let outcome = lastShowMe {
            last = [
                "step": outcome.step, "ok": outcome.ok,
                "error": outcome.error.map { $0 as Any } ?? NSNull(),
                "results": outcome.results, "paths": outcome.paths,
            ] as [String: Any]
        }
        return [
            "running": true,
            "id": tutorial.id,
            "title": tutorial.title,
            "step": index + 1,
            "steps": tutorial.steps.count,
            "text": step.text,
            "optional": step.optional,
            "wait": !step.wait.isEmpty,
            "show_me": !step.showMe.isEmpty,
            "offers": offers,
            "spotlight": step.spotlight.map { $0 as Any } ?? NSNull(),
            "reveal": reveal,
            "reveal_refused": revealRefused.map { $0 as Any } ?? NSNull(),
            "finished": finished,
            "show_me_running": showMeRunning,
            "last_show_me": last,
            "selection_at_start": baseline.selection.map { Int($0) },
            "created": created.map { Int($0) },
            "completed": completed.map { ["step": $0.step, "by": $0.by.rawValue] as [String: Any] },
        ]
    }
}
import AppKit

/// A Show Me in flight: its entries, where it is, and what it has answered.
struct TutorialShowMeRun {
    let entries: [TutorialShowMe]
    let step: Int
    let generation: Int
    var results: [String] = []
    var paths: [String] = []
}

/// Show Me (spec §11 TU-3, TU-9): the step done the way the app already does
/// it, its entries in order, never blocking main.
///
/// **The tool form** resolves TU-2 (9)'s variables, then goes through
/// `AgentLane.shared.submit` pinned to the runner's document — the
/// assistant's path: the argument gate, the lane's lock, ordinary undo — with
/// ask-first answered yes, since the press is the ask. An `export` call's
/// `path` is made free first (`RecordingFiles.uniqueURL`, the Finder's
/// `<stem> (2).<ext>` rule), so a Show Me never overwrites a file, and the
/// outcome names the file. Its completion hops back to main — a documented
/// `DispatchQueue.main.async` seam — and is dropped when the runner has been
/// replaced or exited. **The menu form** looks the path up in the built menu
/// bar for the editor's window (`UIMenu.lookup`, compiled in every build) and
/// runs the item through `UIMenu.perform`, refused when absent, when nothing
/// answers it or its validator greys it, and when nothing handled it.
///
/// An entry that errors stops the list with its own text; the step stays,
/// and the earlier entries' edits stay. Evaluations are held while it runs
/// (`TutorialRunner.trigger`) and one runs after the last entry.
extension TutorialRunner {
    func showMe() throws {
        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
        if showMeRunning { throw TutorialRefusal(sentence: "Show Me is still running.") }
        let entries = currentStep.showMe
        guard !entries.isEmpty else { throw TutorialRefusal(sentence: "This step has no Show Me.") }
        guard document != nil else { throw TutorialRefusal(sentence: "This window has no project.") }
        showMeGeneration += 1
        showMeRunning = true
        showMeRun = TutorialShowMeRun(entries: entries, step: index + 1, generation: showMeGeneration)
        runShowMeEntry(0)
    }

    private func runShowMeEntry(_ at: Int) {
        guard let run = showMeRun else { return }
        guard at < run.entries.count else {
            finishShowMe(error: nil)
            return
        }
        guard let document else {
            finishShowMe(error: "The tutorial's project is no longer open.")
            return
        }
        let before = Set(document.editedProject.snapshot.clips.map(\.id))
        switch run.entries[at] {
        case .menu(let path):
            if let refusal = performMenu(path) {
                finishShowMe(error: refusal)
                return
            }
            showMeRun?.results.append(path.joined(separator: " ▸ "))
            noteCreated(since: before)
            runShowMeEntry(at + 1)
        case .tool(let name, let args):
            let json: String
            do {
                var resolved = try TutorialVariables.resolve(
                    args, selection: selectionAtStart, created: created, snapshot: document.editedProject.snapshot,
                    playhead: document.playhead) as? [String: Any] ?? [:]
                if name == "export", let path = resolved["path"] as? String {
                    let free = Self.freeURL(for: path).path
                    resolved["path"] = free
                    showMeRun?.paths.append(free)
                }
                let data = try JSONSerialization.data(withJSONObject: resolved)
                json = String(decoding: data, as: UTF8.self)
            } catch let refusal as TutorialRefusal {
                finishShowMe(error: refusal.sentence)
                return
            } catch {
                finishShowMe(error: error.localizedDescription)
                return
            }
            let generation = run.generation
            AgentLane.shared.submit(
                tool: name, argumentsJSON: json, document: document,
                askFirst: { _, answer in answer(true) },
                completion: { [weak self] result in
                    DispatchQueue.main.async {
                        guard let self, self.showMeGeneration == generation,
                              self.editor?.tutorialRunner === self
                        else { return }
                        self.toolAnswered(result, entry: at, before: before)
                    }
                })
        }
    }

    private func toolAnswered(_ result: String, entry: Int, before: Set<UInt32>) {
        let reply = (try? JSONSerialization.jsonObject(with: Data(result.utf8))) as? [String: Any]
        let content = reply?["content"] as? [[String: Any]] ?? []
        let text = content.compactMap { $0["text"] as? String }.joined(separator: "\n")
        showMeRun?.results.append(text)
        if (reply?["isError"] as? Bool) ?? true {
            finishShowMe(error: text.isEmpty ? "The call failed." : text)
            return
        }
        if let document { noteCreated(since: before, in: document) }
        runShowMeEntry(entry + 1)
    }

    /// `$created` becomes what this call added, when it added any.
    private func noteCreated(since before: Set<UInt32>, in document: ProjectDocument) {
        let snapshot = document.editedProject.snapshot
        let added = snapshot.clips.map(\.id).filter { !before.contains($0) }
        if !added.isEmpty { created = TutorialVariables.timeOrdered(added, in: snapshot) }
    }

    private func noteCreated(since before: Set<UInt32>) {
        if let document { noteCreated(since: before, in: document) }
    }

    private func finishShowMe(error: String?) {
        guard let run = showMeRun else { return }
        lastShowMe = TutorialShowMeOutcome(
            step: run.step, ok: error == nil, error: error, results: run.results, paths: run.paths)
        showMeRun = nil
        showMeRunning = false
        heldEvaluation = false
        trigger()
    }

    /// The menu form: nil once the item ran, else why not.
    private func performMenu(_ path: [String]) -> String? {
        let shown = path.joined(separator: " ▸ ")
        let window = editor?.view.window
        guard case .item(let item) = UIMenu.lookup(path, window: window) else {
            return "The menu bar has no \(shown)."
        }
        guard let target = UIMenu.target(for: item, window: window),
              UIMenu.isEnabled(item, target: target)
        else { return "\(shown) is not available now." }
        guard UIMenu.perform(item, target: target, window: window) else {
            return "\(shown) was not handled."
        }
        return nil
    }

    /// An `export` path, tilde-expanded, made free by the Finder's rule.
    static func freeURL(for path: String) -> URL {
        let url = URL(fileURLWithPath: (path as NSString).expandingTildeInPath)
        return RecordingFiles.uniqueURL(
            in: url.deletingLastPathComponent(), stem: url.deletingPathExtension().lastPathComponent,
            ext: url.pathExtension)
    }
}
import Foundation

/// Where an inspector section lives: its tab and, on the Clip tab, its
/// sub-tab (nil on every other tab).
struct TutorialSectionHome: Equatable {
    let tab: InspectorTab
    let subTab: ClipSubTab?
}

/// The names a tutorial step may point at (spec §11 TU-2 (6)): the fixed
/// controls, every inspector section with its home, and the two clip
/// references. Nothing resolves a name to a view yet (TU3 does); the table is
/// what `tools/proof/tutorial_check.py` reads, through
/// `tools/proof/tutorial_probe.swift`'s `manifest()`, to refuse a guide page
/// that names a control the app does not have. The checker also fails when
/// `sections` and the section id literals in `app/Sources` differ.
enum TutorialTargets {
    static let sectionPrefix = "section:"
    static let clipPrefix = "clip:"
    static let clipRefs: [String] = ["$selection", "$created"]

    /// Every fixed name, and the control it names, one line each.
    static let fixed: [String: String] = {
        var names: [String: String] = [
            "timeline.clips": "the timeline's clip area",
            "ruler": "the timeline's ruler, where the playhead is dragged",
            "canvas": "the preview canvas",
            "toolbar.play": "the toolbar's Play button",
            "toolbar.timecode": "the toolbar's timecode readout",
            "toolbar.export": "the toolbar's Export… button",
            "timeline.bar.split": "the timeline bar's Split (scissors) button",
            "timeline.bar.trim_start": "the timeline bar's Trim Start button",
            "timeline.bar.trim_end": "the timeline bar's Trim End button",
            "timeline.bar.ripple_delete": "the timeline bar's Ripple Delete button",
            "timeline.bar.add_marker": "the timeline bar's Add Marker button",
            "timeline.bar.duplicate": "the timeline bar's Duplicate button",
            "timeline.bar.add_text": "the timeline bar's Add Text button",
            "timeline.bar.add_shape": "the timeline bar's Add Shape button",
            "sheet.export.format": "the export sheet's Format popup",
            "sheet.export.size": "the export sheet's Size popup",
            "sheet.export.frame_rate": "the export sheet's Frame rate popup",
            "sheet.export.quality": "the export sheet's Quality popup",
            "sheet.export.loudness": "the export sheet's Loudness popup",
            "sheet.export.range": "the export sheet's Range popup",
            "sheet.export.export": "the export sheet's Export… button",
            "sheet.export.add_to_queue": "the export sheet's Add to Queue button",
            "sheet.export.cancel": "the export sheet's Cancel button",
        ]
        for tab in InspectorTab.allCases {
            names["inspector.tab.\(tab.title.lowercased())"] = "the inspector's \(tab.title) tab"
        }
        for subTab in ClipSubTab.allCases {
            names["inspector.sub_tab.\(subTab.rawValue)"] =
                "the Clip tab's \(subTab.title) sub-tab"
        }
        return names
    }()

    /// Every `InspectorSection` id in `app/Sources` and where it lives:
    /// `ClipPane.makeSections()` for the Clip tab's sub-tabs (Shadow, built
    /// by `inspectorShadowSection`, on Picture), `DocumentPane` and
    /// `MediaPane` for theirs.
    static let sections: [String: TutorialSectionHome] = {
        var table: [String: TutorialSectionHome] = [:]
        func clip(_ subTab: ClipSubTab, _ ids: [String]) {
            for id in ids { table[id] = TutorialSectionHome(tab: .clip, subTab: subTab) }
        }
        func other(_ tab: InspectorTab, _ ids: [String]) {
            for id in ids { table[id] = TutorialSectionHome(tab: tab, subTab: nil) }
        }
        clip(.text, [
            "text.content", "text.font", "text.style", "text.outline", "text.backdrop",
            "text.box", "text.animation", "text.presets",
        ])
        clip(.shape, ["shape.kind", "shape.stroke", "shape.fill", "shape.gradient", "shape.arrows"])
        clip(.graphic, ["graphic.source", "graphic.properties", "graphic.size", "graphic.timeline"])
        clip(.picture, [
            "video.transform", "video.crop", "video.corner", "video.chroma", "video.shadow",
            "video.filters", "video.reflection", "video.spotlight", "video.obscure",
        ])
        clip(.color, [
            "video.adjustment", "video.qualifier", "video.light", "video.color", "video.wheels",
            "video.curves", "video.look",
        ])
        clip(.sound, [
            "audio.volume", "audio.fades", "audio.duck", "audio.noise", "audio.compressor",
            "audio.mix",
        ])
        clip(.clip, ["clip.timing", "video.speed", "video.transition", "video.motion"])
        other(.document, ["doc.summary", "doc.canvas", "doc.rate", "doc.appearance", "doc.markers"])
        other(.media, ["media.files", "media.camera_log", "media.hdr10"])
        return table
    }()

    /// The table as JSON-ready values, for the checker:
    /// `{"fixed": [sorted names], "sections": {id: {"tab", "sub_tab" | null}},
    /// "clip_refs", "tabs", "sub_tabs"}`, a tab by its title lowercased and a
    /// sub-tab by its raw value — the spellings a step's `reveal` uses.
    static func manifest() -> [String: Any] {
        var homes: [String: Any] = [:]
        for (id, home) in sections {
            homes[id] = [
                "tab": home.tab.title.lowercased(),
                "sub_tab": home.subTab.map { $0.rawValue as Any } ?? NSNull(),
            ] as [String: Any]
        }
        return [
            "fixed": fixed.keys.sorted(),
            "sections": homes,
            "clip_refs": clipRefs,
            "tabs": InspectorTab.allCases.map { $0.title.lowercased() },
            "sub_tabs": ClipSubTab.allCases.map(\.rawValue),
        ]
    }
}

