import AppKit

/// What a spotlight target name means (spec §11 TU-11 (1)).
enum TutorialTargetKind: Equatable {
    /// A view carrying the name as its accessibility identifier.
    case view(String)
    case inspectorTab(InspectorTab)
    case subTab(ClipSubTab)
    case section(String)
    case clip(TutorialClipSet)
}

/// Where a target is now: the window it is in and its visible rect in that
/// window's content view (clipped to what shows), or no rect and the
/// sentence saying why.
struct TutorialTargetSpot {
    let window: NSWindow?
    let rect: NSRect?
    let reason: String?
}

/// Every name in `TutorialTargets` resolved to a window and a visible rect
/// (spec §11 TU-11): a fixed control by its accessibility identifier (under
/// the editor window's content view, or its attached sheet's for
/// `sheet.export.*`), the inspector's tab strip and the Clip tab's sub-tab
/// strip by their own arithmetic, a section by the shown pane, a clip by the
/// timeline's layout. A target that is hidden, absent or shows nothing
/// answers no rect and one sentence (TU-11 (2)) — never a guessed place.
/// `tools/proof/tutorial_probe.swift` holds `kind(of:)` to the whole table,
/// so a name that does not resolve fails `tutorial_check.py`. Main only.
enum TutorialTargetResolver {
    static let sheetPrefix = "sheet.export."
    private static let tabPrefix = "inspector.tab."
    private static let subTabPrefix = "inspector.sub_tab."

    /// nil for a name outside `TutorialTargets`.
    static func kind(of name: String) -> TutorialTargetKind? {
        if name.hasPrefix(tabPrefix) {
            let title = String(name.dropFirst(tabPrefix.count))
            return InspectorTab.allCases.first { $0.title.lowercased() == title }
                .map { .inspectorTab($0) }
        }
        if name.hasPrefix(subTabPrefix) {
            return ClipSubTab(rawValue: String(name.dropFirst(subTabPrefix.count)))
                .map { .subTab($0) }
        }
        if TutorialTargets.fixed[name] != nil { return .view(name) }
        if name.hasPrefix(TutorialTargets.sectionPrefix) {
            let id = String(name.dropFirst(TutorialTargets.sectionPrefix.count))
            return TutorialTargets.sections[id] != nil ? .section(id) : nil
        }
        if name.hasPrefix(TutorialTargets.clipPrefix) {
            return TutorialClipSet(rawValue: String(name.dropFirst(TutorialTargets.clipPrefix.count)))
                .map { .clip($0) }
        }
        return nil
    }

    static func resolve(
        _ name: String, in editor: EditorViewController, created: [UInt32]
    ) -> TutorialTargetSpot {
        guard let kind = kind(of: name) else {
            return TutorialTargetSpot(
                window: nil, rect: nil, reason: "No spotlight target is called \(name).")
        }
        guard editor.isViewLoaded, let window = editor.view.window else {
            return TutorialTargetSpot(window: nil, rect: nil, reason: "The editor has no window.")
        }
        switch kind {
        case .view(let id):
            return resolveView(id, editor: editor, window: window)
        case .inspectorTab(let tab):
            guard let strip: PanelTabsView = descendant(of: editor.inspector) else {
                return notShown(name, window)
            }
            let r = InspectorTabBadge.tabRect(
                index: tab.rawValue, stripWidth: strip.bounds.width,
                stripHeight: strip.bounds.height)
            return spot(r, in: strip, window: window, otherwise: notOnScreen(name))
        case .subTab(let sub):
            let reason = "The Clip tab does not show the \(sub.title) sub-tab now."
            guard let strip: ClipSubTabsView = descendant(of: editor.inspector),
                  let index = strip.tabs.firstIndex(of: sub)
            else { return TutorialTargetSpot(window: window, rect: nil, reason: reason) }
            return spot(strip.cellRect(index), in: strip, window: window, otherwise: reason)
        case .section(let id):
            let reason = "The inspector does not show the \(id) section now."
            guard let section = editor.inspector?.shownPane()?.1.sections.first(where: { $0.id == id })
            else { return TutorialTargetSpot(window: window, rect: nil, reason: reason) }
            return spot(section.bounds, in: section, window: window, otherwise: reason)
        case .clip(let set):
            return resolveClip(set, editor: editor, window: window, created: created)
        }
    }

    /// A clip target is scrolled into view (as the rename field's reveal
    /// does, both pinned bands allowed for); anything else is left alone —
    /// the runner's reveal already scrolled a section.
    static func bringIntoView(_ name: String, in editor: EditorViewController, created: [UInt32]) {
        guard case .clip(let set)? = kind(of: name), let timeline = editor.timeline,
              let rect = clipRect(set, editor: editor, timeline: timeline, created: created)
        else { return }
        var reveal = rect
        reveal.origin.x -= TimelineLayout.headerWidth
        reveal.size.width += TimelineLayout.headerWidth
        reveal.origin.y -= TimelineLayout.rulerHeight
        reveal.size.height += TimelineLayout.rulerHeight
        timeline.content.scrollToVisible(reveal)
    }

    // MARK: - The kinds

    private static func resolveView(
        _ id: String, editor: EditorViewController, window: NSWindow
    ) -> TutorialTargetSpot {
        var holder = window
        if id.hasPrefix(sheetPrefix) {
            guard let sheet = window.attachedSheet else {
                return TutorialTargetSpot(
                    window: nil, rect: nil, reason: "The export sheet is not open.")
            }
            holder = sheet
        }
        guard let root = holder.contentView, let view = firstShown(id, under: root) else {
            return notShown(id, holder)
        }
        if id == "timeline.clips", let timeline = editor.timeline {
            let r = laneArea(timeline).intersection(view.bounds)
            return spot(r, in: view, window: holder, otherwise: notOnScreen(id))
        }
        return spot(view.bounds, in: view, window: holder, otherwise: notOnScreen(id))
    }

    private static func resolveClip(
        _ set: TutorialClipSet, editor: EditorViewController, window: NSWindow,
        created: [UInt32]
    ) -> TutorialTargetSpot {
        let none = set == .selection ? "No clip is selected." : "No clip has been made yet."
        guard let timeline = editor.timeline else {
            return TutorialTargetSpot(window: window, rect: nil, reason: none)
        }
        guard let r = clipRect(set, editor: editor, timeline: timeline, created: created) else {
            return TutorialTargetSpot(window: window, rect: nil, reason: none)
        }
        return spot(
            r.intersection(laneArea(timeline)), in: timeline.content, window: window,
            otherwise: "The clip is not on screen now.")
    }

    /// The clip's bar in the timeline content's coordinates: the earliest of
    /// the current selection, or of the runner's `$created`.
    private static func clipRect(
        _ set: TutorialClipSet, editor: EditorViewController, timeline: TimelineView,
        created: [UInt32]
    ) -> NSRect? {
        let snapshot = timeline.snapshot
        let ids: [UInt32]
        switch set {
        case .selection: ids = Array(editor.document?.selection ?? [])
        case .created: ids = created
        }
        guard let first = TutorialVariables.timeOrdered(ids, in: snapshot).first,
              let clip = snapshot.clips.first(where: { $0.id == first }),
              let index = snapshot.trackIndex(of: clip.track)
        else { return nil }
        return timeline.layout.clipRect(clip, row: timeline.layout.row(forTrackIndex: index))
    }

    /// The clip area as it shows: the content's visible rect less the pinned
    /// ruler band (top) and header column (left), which paint over it.
    static func laneArea(_ timeline: TimelineView) -> NSRect {
        var r = timeline.content.visibleRect
        let top = max(r.minY, timeline.ruler.frame.maxY)
        let left = max(r.minX, timeline.headers.frame.maxX)
        r.size.height = max(0, r.maxY - top)
        r.origin.y = top
        r.size.width = max(0, r.maxX - left)
        r.origin.x = left
        return r
    }

    // MARK: - Helpers

    /// `r` (in `view`'s coordinates) cut to what `view` shows and given in
    /// the window's content view, or no rect and `otherwise`.
    private static func spot(
        _ r: NSRect, in view: NSView, window: NSWindow, otherwise: String
    ) -> TutorialTargetSpot {
        guard let content = window.contentView, view.window === window,
              !view.isHiddenOrHasHiddenAncestor
        else { return TutorialTargetSpot(window: window, rect: nil, reason: otherwise) }
        let visible = r.intersection(view.visibleRect)
        guard !visible.isNull, visible.width > 0, visible.height > 0 else {
            return TutorialTargetSpot(window: window, rect: nil, reason: otherwise)
        }
        return TutorialTargetSpot(
            window: window, rect: view.convert(visible, to: content), reason: nil)
    }

    private static func notOnScreen(_ name: String) -> String {
        let description = TutorialTargets.fixed[name] ?? "The \(name) control"
        return description.prefix(1).uppercased() + description.dropFirst() + " is not on screen now."
    }

    private static func notShown(_ name: String, _ window: NSWindow) -> TutorialTargetSpot {
        TutorialTargetSpot(window: window, rect: nil, reason: notOnScreen(name))
    }

    /// The first view under `root`, breadth first, whose identifier is `id`
    /// and that is not hidden.
    private static func firstShown(_ id: String, under root: NSView) -> NSView? {
        var queue: [NSView] = [root]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if view.accessibilityIdentifier() == id, !view.isHiddenOrHasHiddenAncestor {
                return view
            }
            queue.append(contentsOf: view.subviews)
        }
        return nil
    }

    /// The first `T` among the inspector's descendants, breadth first.
    private static func descendant<T: NSView>(of inspector: InspectorViewController?) -> T? {
        guard let inspector, inspector.isViewLoaded else { return nil }
        var queue: [NSView] = [inspector.view]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if let found = view as? T, !found.isHiddenOrHasHiddenAncestor { return found }
            queue.append(contentsOf: view.subviews)
        }
        return nil
    }
}

