    /// Shows the ring on `target` in `editor`'s window (nil hides it). A new
    /// step first brings a clip target into view.
    func show(
        _ target: String?, in editor: EditorViewController, created: [UInt32], stepChanged: Bool
    ) {
        guard let target else {
            hide()
            return
        }
        self.target = target
        self.editor = editor
        self.created = created
        if stepChanged {
            TutorialTargetResolver.bringIntoView(target, in: editor, created: created)
        }
        observe(editor)
        refresh()
    }

    /// No target: the ring out and every observer removed.
    func hide() {
        target = nil
        spot = nil
        removeObservers()
        orderOut()
    }

    /// One re-resolve on the next main turn, however many ask before it.
    func refreshSoon() {
        guard target != nil, !refreshPending else { return }
        refreshPending = true
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            self.refreshPending = false
            self.refresh()
        }
    }

    /// The ring view's frame in `window.contentView`'s coordinates, when the
    /// ring shows over that window.
    func ringFrame(in window: NSWindow) -> NSRect? {
        guard self.window.isVisible, parent === window else { return nil }
        return shownFrame
    }

    // MARK: - Resolving

    private func refresh() {
        guard let target, let editor else {
            hide()
            return
        }
        let created = editor.tutorialRunner?.created ?? self.created
        let resolved = TutorialTargetResolver.resolve(target, in: editor, created: created)
        spot = resolved
        guard let rect = resolved.rect, let holder = resolved.window, holder.isVisible,
              !holder.isMiniaturized, let content = holder.contentView
        else {
            orderOut()
            return
        }
        if parent !== holder {
            parent?.removeChildWindow(window)
            holder.addChildWindow(window, ordered: .above)
            parent = holder
        }
        let screenFrame = holder.convertToScreen(content.convert(content.bounds, to: nil))
        window.setFrame(screenFrame, display: false)
        let frame = TutorialRingView.frame(for: rect, in: content.bounds)
        shownFrame = frame
        let top = content.isFlipped ? frame.minY : content.bounds.height - frame.maxY
        ring.frame = NSRect(x: frame.minX, y: top, width: frame.width, height: frame.height)
        ring.needsDisplay = true
        if !window.isVisible { window.orderFront(nil) }
    }

    private func orderOut() {
        shownFrame = nil
        parent?.removeChildWindow(window)
        parent = nil
        window.orderOut(nil)
    }

    // MARK: - Following layout

    /// Any view frame or bounds change in the editor window or its sheet, the
    /// window's resize and sheets, the served document's changes and the
    /// runner's posts each ask for one refresh. Registered once per editor
    /// window while a target is shown.
    private func observe(_ editor: EditorViewController) {
        guard let editorWindow = editor.view.window else { return }
        if observedWindow === editorWindow, !observers.isEmpty { return }
        removeObservers()
        observedWindow = editorWindow
        let center = NotificationCenter.default
        for name in [NSView.frameDidChangeNotification, NSView.boundsDidChangeNotification] {
            observers.append(
                center.addObserver(forName: name, object: nil, queue: nil) { [weak self] note in
                    self?.viewChanged(note.object as? NSView)
                })
        }
        for name in [
            NSWindow.didResizeNotification, NSWindow.willBeginSheetNotification,
            NSWindow.didEndSheetNotification,
        ] {
            observers.append(
                center.addObserver(forName: name, object: editorWindow, queue: nil) {
                    [weak self] _ in self?.refreshSoon()
                })
        }
        observers.append(
            center.addObserver(
                forName: ProjectDocument.projectDocumentDidChange, object: editor.document,
                queue: nil
            ) { [weak self] _ in self?.refreshSoon() })
        observers.append(
            center.addObserver(forName: .tutorialRunnerDidChange, object: nil, queue: nil) {
                [weak self] _ in self?.refreshSoon()
            })
    }

    /// Kept only for a view in the editor window or its sheet — never the
    /// spotlight's own.
    private func viewChanged(_ view: NSView?) {
        guard let changed = view?.window, changed !== window,
              let editorWindow = observedWindow,
              changed === editorWindow || changed === editorWindow.attachedSheet
        else { return }
        refreshSoon()
    }

    private func removeObservers() {
        for observer in observers { NotificationCenter.default.removeObserver(observer) }
        observers = []
        observedWindow = nil
    }
}

import AppKit

/// A coach panel button; the raw value is its id in `tutorial_press` and the
/// panel's state, and `tutorial.<raw>` its accessibility id.
enum TutorialPanelButton: String, CaseIterable {
    case back, showMe = "show_me", skip, next, exit, openPractice = "open_practice", close

    var title: String {
        switch self {
        case .back: return "Back"
        case .showMe: return "Show Me"
        case .skip: return "Skip"
        case .next: return "Next"
        case .exit: return "Exit"
        case .openPractice: return "Open Practice Project"
        case .close: return "Close"
        }
    }
}

/// The coach panel's window (spec §11 TU-4, TU-10 (4)): never key, never main,
/// so typing stays in the editor's field and a click on a button acts with
/// the editor still key.
final class TutorialPanel: NSPanel {
    override var canBecomeKey: Bool { false }
    override var canBecomeMain: Bool { false }
}

/// The coach panel (spec §11 TU-10 (4)): a view over the runner's state —
/// the title, "Step n of m" with the tick, the step's sentence with its bold
/// and code spans, a muted message, and the buttons the runner offers — or
/// the finish, or an offer of the practice project. It decides nothing: a
/// press goes to `onPress` (the coach). The tick holds a met wait's step for
/// `tickHold` on a main-thread `Timer`, a documented seam, then renders the
/// runner, which it holds only weakly. Main only.
final class TutorialPanelController: NSWindowController {
    static let tickHold: TimeInterval = 0.8
    static let cardWidth: CGFloat = 320
    private static let inset: CGFloat = 16

    var onPress: ((TutorialPanelButton) -> Void)?
    /// The served editor's project path for the state, set by the coach.
    var projectPath: (() -> String?)?

    private let titleLabel = NSTextField(wrappingLabelWithString: "")
    private let progressLabel = NSTextField(labelWithString: "")
    private let tickView = NSImageView()
    private let textLabel = NSTextField(wrappingLabelWithString: "")
    private let messageLabel = NSTextField(wrappingLabelWithString: "")
    private let buttonRow = NSStackView()
    private let card = NSStackView()
    private var buttons: [TutorialPanelButton: StickerButton] = [:]
    private var shown: [TutorialPanelButton] = []

    private var mode = "step"
    private var tutorialID: String?
    private var plainText = ""
    private var message: String?
    private var ticking = false
    private var tickTimer: Timer?
    private weak var runner: TutorialRunner?
    /// The runner and its `lastCompleted` the panel last saw, so only a NEW
    /// step left by its wait ticks.
    private var seen: (runner: ObjectIdentifier, step: Int, by: TutorialAdvance)?

    init() {
        let panel = TutorialPanel(
            contentRect: NSRect(x: 0, y: 0, width: Self.cardWidth, height: 160),
            styleMask: [.titled, .nonactivatingPanel, .utilityWindow], backing: .buffered,
            defer: false)
        panel.title = "Tutorial"
        panel.level = .floating
        panel.hidesOnDeactivate = false
        panel.becomesKeyOnlyIfNeeded = true
        panel.isReleasedWhenClosed = false
        panel.isExcludedFromWindowsMenu = true
        panel.backgroundColor = DS.chromeBackground
        super.init(window: panel)
        build(in: panel)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("TutorialPanelController does not support NSCoder")
    }

    // MARK: - Layout

    private func build(in panel: NSPanel) {
        let width = Self.cardWidth - 2 * Self.inset
        for (label, id) in [
            (titleLabel, "tutorial.title"), (progressLabel, "tutorial.progress"),
            (textLabel, "tutorial.text"), (messageLabel, "tutorial.message"),
        ] {
            label.isSelectable = false
            label.isEditable = false
            label.setAccessibilityIdentifier(id)
        }
        for label in [titleLabel, textLabel, messageLabel] {
            label.preferredMaxLayoutWidth = width
        }
        titleLabel.font = DS.sans(14, weight: .semibold)
        titleLabel.textColor = DS.textStrong
        progressLabel.font = DS.sans(11)
        progressLabel.textColor = DS.textMuted
        messageLabel.font = DS.sans(12)
        messageLabel.textColor = DS.textMuted
        tickView.image = NSImage(
            systemSymbolName: "checkmark.circle.fill", accessibilityDescription: "Done")
        tickView.contentTintColor = DS.accent
        tickView.setAccessibilityIdentifier("tutorial.tick")
        tickView.isHidden = true

        let progress = NSStackView(views: [progressLabel, tickView])
        progress.orientation = .horizontal
        progress.spacing = 4

        buttonRow.orientation = .horizontal
        buttonRow.spacing = 6
        for kind in TutorialPanelButton.allCases {
            let style: StickerButton.Style =
                kind == .showMe || kind == .next || kind == .openPractice ? .primary : .secondary
            let button = StickerButton(
                title: kind.title, style: style, target: self, action: #selector(pressed(_:)))
            button.setAccessibilityIdentifier("tutorial." + kind.rawValue)
            buttons[kind] = button
        }

        card.orientation = .vertical
        card.alignment = .leading
        card.spacing = 8
        card.edgeInsets = NSEdgeInsets(
            top: Self.inset, left: Self.inset, bottom: Self.inset, right: Self.inset)
        for view in [titleLabel, progress, textLabel, messageLabel, buttonRow] as [NSView] {
            card.addArrangedSubview(view)
        }
        for view in [titleLabel, textLabel, messageLabel] as [NSView] {
            view.widthAnchor.constraint(equalToConstant: width).isActive = true
        }
        card.setCustomSpacing(14, after: messageLabel)
        card.translatesAutoresizingMaskIntoConstraints = false
        card.widthAnchor.constraint(equalToConstant: Self.cardWidth).isActive = true

        // The card pinned at the top-left of a plain root, the window sized to
        // its fitting size (the recorder panel's rule).
        let root = NSView()
        root.addSubview(card)
        NSLayoutConstraint.activate([
            card.topAnchor.constraint(equalTo: root.topAnchor),
            card.leadingAnchor.constraint(equalTo: root.leadingAnchor),
        ])
        panel.contentView = root
    }

    @objc private func pressed(_ sender: NSButton) {
        guard let kind = buttons.first(where: { $0.value === sender })?.key else { return }
        onPress?(kind)
    }

    // MARK: - Showing

    /// The runner's state, or — when it just left a step by its met wait —
    /// that step with the tick for `tickHold` first.
    func showStep(_ runner: TutorialRunner) {
        self.runner = runner
        let id = ObjectIdentifier(runner)
        let last = runner.lastCompleted
        let before = seen
        seen = last.map { (id, $0.step, $0.by) }
        if let last, last.by == .wait,
           before?.runner != id || before?.step != last.step || before?.by != last.by
        {
            showTick(runner, step: last.step)
            return
        }
        if before?.runner != id { cancelTick() }
        if ticking { return }
        render(runner)
    }

    /// An offer: what is missing and the practice project (spec §11 TU-5,
    /// TU-10 (2)).
    func showOffer(title: String, sentence: String, message: String?, tutorial: String? = nil) {
        cancelTick()
        runner = nil
        seen = nil
        mode = "offer"
        tutorialID = tutorial
        titleLabel.stringValue = title
        progressLabel.stringValue = ""
        progressLabel.isHidden = true
        setText(sentence)
        setMessage(message)
        setButtons([.openPractice, .close], enabled: [.openPractice, .close])
        fit()
    }

    private func render(_ runner: TutorialRunner) {
        let tutorial = runner.tutorial
        tutorialID = tutorial.id
        titleLabel.stringValue = TutorialCoach.displayTitle(tutorial.title)
        progressLabel.isHidden = false
        tickView.isHidden = true
        buttons[.exit]?.title = runner.finished ? "Done" : TutorialPanelButton.exit.title
        if runner.finished {
            mode = "finished"
            progressLabel.stringValue = "Finished"
            setText("You finished this tutorial.")
            setMessage(Self.message(runner))
            setButtons([.back, .exit], enabled: [.back, .exit])
        } else {
            mode = "step"
            progressLabel.stringValue = "Step \(runner.index + 1) of \(tutorial.steps.count)"
            setText(runner.currentStep.text)
            setMessage(Self.message(runner))
            let offered = runner.offers.compactMap(TutorialPanelButton.init(rawValue:))
            setButtons(offered, enabled: runner.showMeRunning ? [.exit] : Set(offered))
        }
        fit()
    }

    private func showTick(_ runner: TutorialRunner, step: Int) {
        let tutorial = runner.tutorial
        guard step >= 1, step <= tutorial.steps.count else {
            render(runner)
            return
        }
        cancelTick()
        ticking = true
        mode = "step"
        tutorialID = tutorial.id
        titleLabel.stringValue = TutorialCoach.displayTitle(tutorial.title)
        progressLabel.isHidden = false
        progressLabel.stringValue = "Step \(step) of \(tutorial.steps.count)"
        tickView.isHidden = false
        setText(tutorial.steps[step - 1].text)
        setButtons(shown, enabled: [])
        fit()
        tickTimer = Timer.scheduledTimer(withTimeInterval: Self.tickHold, repeats: false) {
            [weak self] _ in
            guard let self else { return }
            self.ticking = false
            self.tickTimer = nil
            if let runner = self.runner { self.render(runner) }
        }
    }

    private func cancelTick() {
        tickTimer?.invalidate()
        tickTimer = nil
        ticking = false
    }

    /// The first that holds: the last Show Me's error on its own step, where
    /// a Show Me export was sent, the reveal's refusal.
    private static func message(_ runner: TutorialRunner) -> String? {
        if let last = runner.lastShowMe, let error = last.error, !runner.finished,
           last.step == runner.index + 1
        {
            return error
        }
        if let path = runner.lastShowMe?.paths.last {
            return "Show Me exports to \((path as NSString).abbreviatingWithTildeInPath)."
        }
        return runner.revealRefused
    }

    private func setText(_ text: String) {
        plainText = TutorialSentence.plain(text)
        textLabel.attributedStringValue = TutorialSentence.attributed(
            text, font: DS.sans(13), boldFont: DS.sans(13, weight: .semibold),
            codeFont: DS.mono(12), color: DS.textStrong)
    }

    private func setMessage(_ text: String?) {
        message = text
        messageLabel.stringValue = text ?? ""
        messageLabel.isHidden = text == nil
    }

    private func setButtons(_ list: [TutorialPanelButton], enabled: Set<TutorialPanelButton>) {
        shown = list
        for view in buttonRow.arrangedSubviews { buttonRow.removeArrangedSubview(view) }
        for view in buttonRow.subviews { view.removeFromSuperview() }
        for kind in list {
            guard let button = buttons[kind] else { continue }
            button.isEnabled = enabled.contains(kind)
            buttonRow.addArrangedSubview(button)
        }
    }

    /// Sized to the card, keeping the top-left (the recorder panel's rule).
    private func fit() {
        guard let window else { return }
        card.layoutSubtreeIfNeeded()
        let size = card.fittingSize
        var frame = window.frameRect(forContentRect: NSRect(origin: .zero, size: size))
        let current = window.frame
        frame.origin = NSPoint(x: current.minX, y: current.maxY - frame.height)
        window.setFrame(frame, display: window.isVisible)
    }

    // MARK: - The dev tools' reads

    /// `tutorial_state`'s and `tutorial_press`'s `panel`.
    func state() -> [String: Any] {
        [
            "shown": window?.isVisible ?? false,
            "mode": mode,
            "tutorial": tutorialID.map { $0 as Any } ?? NSNull(),
            "title": titleLabel.stringValue,
            "progress": progressLabel.isHidden ? "" : progressLabel.stringValue,
            "text": plainText,
            "message": message.map { $0 as Any } ?? NSNull(),
            "buttons": shown.map(\.rawValue),
            "enabled": shown.filter { buttons[$0]?.isEnabled == true }.map(\.rawValue),
            "tick": ticking,
            "project": projectPath?().map { $0 as Any } ?? NSNull(),
        ]
    }

    /// The button, when it is shown and enabled.
    func button(_ b: TutorialPanelButton) -> NSButton? {
        guard shown.contains(b), let button = buttons[b], button.isEnabled else { return nil }
        return button
    }
}

