            systemSymbolName: "checkmark.circle.fill", accessibilityDescription: "Done")
        tickView.contentTintColor = DS.accent
        tickView.setAccessibilityIdentifier("tutorial.tick")
        tickView.isHidden = true

        let progress = NSStackView(views: [progressLabel, tickView])
        progress.orientation = .horizontal
        progress.spacing = 4

        buttonRow.orientation = .horizontal
        buttonRow.spacing = 6
        for kind in TutorialPanelButton.allCases {
            let style: StickerButton.Style =
                kind == .showMe || kind == .next || kind == .openPractice ? .primary : .secondary
