        ) { [weak self] note in
            guard let runner = note.object as? TutorialRunner else { return }
            self?.runnerChanged(runner)
        }
    }

    // MARK: - Starting

    /// Help ▸ Tutorials ▸ <page> ▸ <tutorial>.
    func start(id: String) {
        observe()
        let library: TutorialLibrary
        do {
            library = try TutorialLibrary.bundled()
        } catch {
            showOffer(id: id, title: "Tutorial", sentence: error.localizedDescription, beside: nil)
            return
        }
        guard let tutorial = library.tutorial(id: id) else {
            let sentence = library.refused[id].map { "The tutorial \(id) does not read: \($0)." }
                ?? "No tutorial is called \(id)."
            showOffer(id: id, title: "Tutorial", sentence: sentence, beside: Self.frontEditor())
            return
        }
        let title = Self.displayTitle(tutorial.title)
        guard let editor = Self.frontEditor() else {
            showOffer(id: id, title: title, sentence: Self.noWindowSentence, beside: nil)
            return
        }
        do {
            offer = nil
            try TutorialRunner.start(tutorial, in: editor)
        } catch let refusal as TutorialRefusal {
            showOffer(id: id, title: title, sentence: refusal.sentence, beside: editor)
        } catch {
            showOffer(id: id, title: title, sentence: error.localizedDescription, beside: editor)
        }
    }

    /// A panel button.
    func press(_ b: TutorialPanelButton) {
        switch b {
        case .openPractice:
            openPractice()
            return
        case .close:
            offer = nil
            render()
            return
        default:
            break
        }
        guard let runner = editor?.tutorialRunner else { return }
        do {
            switch b {
            case .back: try runner.back()
            case .showMe: try runner.showMe()
            case .skip: try runner.skip()
            case .next: try runner.next()
            default: runner.exit()
            }
        } catch {
            NSSound.beep()
        }
    }

    /// Opens the practice copy and starts the offered tutorial in it; a
    /// failure stays in the offer as its message.
    private func openPractice() {
        guard let pending = offer else { return }
        let sentence = (panel?.state()["text"] as? String) ?? ""
        do {
            let document = try PracticeProject.open()
            let opened = document.windowControllers
                .compactMap { $0.contentViewController as? EditorViewController }.first
            guard let opened, let tutorial = try TutorialLibrary.bundled().tutorial(id: pending.id)
            else {
                offer = nil
                render()
                return
            }
            offer = nil
            try TutorialRunner.start(tutorial, in: opened)
        } catch let refusal as TutorialRefusal {
            showOffer(
                id: pending.id, title: pending.title, sentence: sentence, beside: offerEditor,
                message: refusal.sentence)
        } catch {
            showOffer(
                id: pending.id, title: pending.title, sentence: sentence, beside: offerEditor,
                message: error.localizedDescription)
        }
    }

    private func showOffer(
        id: String, title: String, sentence: String, beside: EditorViewController?,
        message: String? = nil
    ) {
        offer = (id, title)
        offerEditor = beside
        spotlight.hide()
        let panel = ensurePanel()
        panel.showOffer(
            title: title, sentence: sentence, message: message ?? Self.offerLine, tutorial: id)
        place(beside: beside)
        panel.window?.orderFront(nil)
    }

    // MARK: - Serving

    private func runnerChanged(_ runner: TutorialRunner) {
        guard let changed = runner.editor else { return }
        if changed !== editor {
            // A stale runner of another window (an exit there) changes nothing.
            guard changed.tutorialRunner === runner else { return }
            let previous = editor
            serve(changed)
            previous?.tutorialRunner?.exit()
        }
        if changed.tutorialRunner === runner { offer = nil }
        render()
    }

    /// The served window's step in the panel and its target in the ring, or
    /// both hidden once no tutorial runs there.
    private func render() {
        if offer != nil { return }
        guard let editor, let runner = editor.tutorialRunner,
              let window = editor.view.window, !window.isMiniaturized
        else {
            hideAll()
            if editor?.tutorialRunner == nil { unserve() }
            return
        }
        let panel = ensurePanel()
        panel.showStep(runner)
        place(beside: editor)
        panel.window?.orderFront(nil)
        let step = (ObjectIdentifier(runner), runner.index, runner.finished)
        let changed = lastStep.map { $0 != step } ?? true
        lastStep = step
        spotlight.show(
            runner.finished ? nil : runner.currentStep.spotlight, in: editor,
            created: runner.created, stepChanged: changed)
    }

    private func hideAll() {
        panel?.window?.orderOut(nil)
        spotlight.hide()
        lastStep = nil
    }

    private func serve(_ next: EditorViewController) {
        unserve()
        editor = next
        guard let window = next.view.window else { return }
        let center = NotificationCenter.default
        windowObservers.append(
            center.addObserver(forName: NSWindow.willCloseNotification, object: window, queue: nil) {
                [weak self] _ in self?.servedWindowWillClose()
            })
        for name in [NSWindow.didMoveNotification, NSWindow.didResizeNotification] {
            windowObservers.append(
                center.addObserver(forName: name, object: window, queue: nil) { [weak self] _ in
                    guard let self, self.panel?.window?.isVisible == true else { return }
                    self.place(beside: self.offer == nil ? self.editor : self.offerEditor)
                })
        }
        for name in [NSWindow.didMiniaturizeNotification, NSWindow.didDeminiaturizeNotification] {
            windowObservers.append(
                center.addObserver(forName: name, object: window, queue: nil) { [weak self] _ in
                    self?.render()
                })
        }
    }

    private func unserve() {
        for observer in windowObservers { NotificationCenter.default.removeObserver(observer) }
        windowObservers = []
        editor = nil
    }

    /// Closing the window or the project ends the tutorial.
    private func servedWindowWillClose() {
        let closing = editor
        unserve()
        closing?.tutorialRunner?.exit()
        closing?.tutorialRunner = nil
        if offer == nil || offerEditor === closing { offer = nil }
        hideAll()
    }

    private func ensurePanel() -> TutorialPanelController {
        if let panel { return panel }
        let made = TutorialPanelController()
        made.onPress = { [weak self] button in self?.press(button) }
        made.projectPath = { [weak self] in
            guard let document = self?.editor?.document else { return nil }
            return AgentServer.path(of: document)
        }
        panel = made
        return made
    }

    // MARK: - Placement

    /// Beside `editor`'s window by `panelOrigin`, or centred on the main
    /// screen with no window.
    private func place(beside editor: EditorViewController?) {
        guard let window = panel?.window else { return }
        let size = window.frame.size
        if let editorWindow = editor?.view.window,
           let screen = (editorWindow.screen ?? NSScreen.main)?.visibleFrame
        {
            window.setFrameOrigin(
                Self.panelOrigin(editor: editorWindow.frame, panel: size, screen: screen))
        } else if let screen = (NSScreen.main ?? NSScreen.screens.first)?.visibleFrame {
            window.setFrameOrigin(
                NSPoint(x: screen.midX - size.width / 2, y: screen.midY - size.height / 2))
        }
    }

    /// Right of the editor window by 12 pt with the tops aligned when that
    /// fits `screen`; else left of it; else inside its bottom-left corner,
    /// 16 pt in.
    static func panelOrigin(editor: NSRect, panel: NSSize, screen: NSRect) -> NSPoint {
        let top = editor.maxY - panel.height
        let right = NSRect(
            origin: NSPoint(x: editor.maxX + besideGap, y: top), size: panel)
        if screen.contains(right) { return right.origin }
        let left = NSRect(
            origin: NSPoint(x: editor.minX - besideGap - panel.width, y: top), size: panel)
        if screen.contains(left) { return left.origin }
        return NSPoint(x: editor.minX + cornerInset, y: editor.minY + cornerInset)
    }

    // MARK: - Helpers

    /// The guide's title with its first character uppercased, the rest as
    /// written ("Change a clip's volume").
    static func displayTitle(_ title: String) -> String {
        title.prefix(1).uppercased() + title.dropFirst()
    }

    /// The main window's editor, else the first editor in window order.
    static func frontEditor() -> EditorViewController? {
        if let main = NSApp.mainWindow?.contentViewController as? EditorViewController {
            return main
        }
        return NSApp.orderedWindows.lazy
            .compactMap { $0.contentViewController as? EditorViewController }.first
    }
}

