/// page holding its tutorials, filled from the bundled `Tutorials.json`, then a
/// separator, then Open Practice Project, which opens the bundled practice
/// project as an untitled copy (`PracticeProject.open()`);
/// `new_project {practice: true}` is its MCP mirror, and `tutorial_start` /
/// `tutorial_press` reach the tutorials (dev tools).
///
/// Nil-target selectors on the delegate, like `showGraphicsReference`, so they
/// resolve with no document open; `AppDelegate.validateMenuItem` enables Open
/// Practice Project while the bundle holds the practice project, and a
/// tutorial item always (no validator arm: with no window the coach panel
/// offers the practice project). No key equivalent: every bare letter belongs
/// to the editor's own `keyDown` (spec §9).
extension AppDelegate {

    /// "Tutorials": the page submenus, a separator, Open Practice Project last.
    /// A library that does not read gives Open Practice Project alone.
    func tutorialsMenu() -> NSMenu {
        TutorialCoach.shared.observe()
        let menu = NSMenu(title: "Tutorials")
        let pages = ((try? TutorialLibrary.bundled())?.pages ?? []).filter { !$0.tutorials.isEmpty }
        for page in pages {
            let submenu = NSMenu(title: page.title)
            for tutorial in page.tutorials {
                let entry = item(
                    TutorialCoach.displayTitle(tutorial.title),
                    #selector(AppDelegate.startTutorial(_:)))
                entry.representedObject = tutorial.id
                submenu.addItem(entry)
            }
            menu.addItem(submenuItem(submenu))
        }
        if !pages.isEmpty { menu.addItem(.separator()) }
