def check_model(document: dict, facts: dict, accepted: set) -> list:
    """The runner's model against the checker (spec §11 TU-8 (1)): every
    tutorial the checker accepted decodes, each model mutant and nothing else
    is refused, the fixture page decodes, and a JSON 1 is not a boolean."""
    problems = []

    def add(message, page=MODEL_PAGE, tid=None):
        problems.append(Problem(page, 0, tid, None, message))

    model = facts.get("model")
    if not isinstance(model, dict) or "error" in model:
        add("the probe gave no model verdicts: "
            + (str(model["error"]) if isinstance(model, dict) else "no `model` in its facts"))
        return problems
    guide = model.get("guide") or {}
    for page in document["pages"]:
        for tutorial in page["tutorials"]:
            tid = tutorial["id"]
            if tid not in accepted:
                continue
            if tid not in guide:
                add("the model gave it no verdict", page=page["page"], tid=tid)
            elif guide[tid] is not None:
                add(f"the checker accepts it and the model refuses it: {guide[tid]}",
                    page=page["page"], tid=tid)
    mutants = model.get("mutants") or {}
    for name in MODEL_MUTANTS:
        verdict = mutants.get(name)
        if not isinstance(verdict, str) or not verdict:
            add(f"the model decoded the mutant {name!r}, which the checker refuses")
    if model.get("control", "") is not None:
        add(f"the model refused the fixture page: {model.get('control')}")
    if facts.get("filter_number_matches") is not False:
        add("a clip filter's JSON 1 matched a boolean key "
            f"(filter_number_matches is {facts.get('filter_number_matches')!r})")
    return problems


# ---------------------------------------------------------------------------


def line(problem) -> str:
    where = problem.page
    if problem.tutorial is not None:
        where += f" tutorial {problem.tutorial}"
    if problem.step is not None:
        where += f" step {problem.step}"
    message = problem.message if not problem.line else f"line {problem.line}: {problem.message}"
    return f"FAIL {where}: {message}"


def run(guide, facts, inventory, sources, practice):
    document, problems = parse_guide(guide)
    problems = problems + check(document, facts, inventory, sources)
    refused = {p.tutorial for p in problems if p.tutorial is not None}
    accepted = {t["id"] for page in document["pages"] for t in page["tutorials"]} - refused

