    static func frontEditor() -> EditorViewController? {
        func serving(_ window: NSWindow?) -> EditorViewController? {
            guard let window, window.isVisible,
                  let editor = window.contentViewController as? EditorViewController,
                  editor.document != nil
            else { return nil }
            return editor
        }
        if let main = serving(NSApp.mainWindow) { return main }
        return NSApp.orderedWindows.lazy.compactMap { serving($0) }.first
    }''')
